src/ArchAdapterBondingCurve.sol.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ArchToken} from "./ArchToken.sol";
import {ArchTokenDeployLib} from "./lib/ArchTokenDeployLib.sol";
import {IArchStockSwapExecutor} from "./interfaces/IArchStockSwapExecutor.sol";
import {IArchLaunchLiquidityAdapter} from "./interfaces/IArchLaunchLiquidityAdapter.sol";
import {ISwapRouter, IWETH9} from "./interfaces/IUniswapV3.sol";

/// @title ArchAdapterBondingCurve
/// @notice Constant-product fair launch that graduates through one immutable
///         AMM-family adapter when its exact real-ETH threshold is reached.
contract ArchAdapterBondingCurve is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint16 public constant TRADE_FEE_BPS = 100;

    struct Infra {
        address payable treasury;
        IArchLaunchLiquidityAdapter liquidityAdapter;
        ISwapRouter swapRouter;
        IWETH9 weth;
        uint24 tokenPoolFee;
        uint24 stockPoolFee;
        IArchStockSwapExecutor stockSwapExecutor;
        address keeper;
    }

    struct TokenConfig {
        string name;
        string symbol;
        uint256 totalSupply;
        uint16 taxBps;
        IERC20 stock;
        uint16 creatorFeeBps;
    }

    struct CurveConfig {
        uint16 curvePct;
        uint128 virtualEth;
        uint128 gradEth;
        uint24 poolFee;
    }

    address public immutable CREATOR;
    address payable public immutable TREASURY;
    IArchLaunchLiquidityAdapter public immutable LIQUIDITY_ADAPTER;
    ISwapRouter public immutable SWAP_ROUTER;
    IWETH9 public immutable WETH;
    uint24 public immutable POOL_FEE;
    uint24 public immutable STOCK_POOL_FEE;
    address public immutable KEEPER;

    string public tokenName;
    string public tokenSymbol;
    uint256 public immutable TOTAL_SUPPLY;
    uint16 public immutable TAX_BPS;
    uint16 public immutable CREATOR_FEE_BPS;
    IERC20 public immutable STOCK;

    uint256 public immutable CURVE_SUPPLY;
    uint256 public immutable LP_SUPPLY;
    uint256 public immutable K;
    uint128 public immutable GRAD_ETH;

    ArchToken public token;
    address public pair;
    bytes32 public poolId;
    uint256 public ethReserve;
    uint256 public tokenReserve;
    uint256 public realEthCollected;
    bool public graduated;

    event Bought(address indexed buyer, uint256 ethIn, uint256 fee, uint256 tokensOut);
    event Sold(address indexed seller, uint256 tokensIn, uint256 ethOut, uint256 fee);
    event Graduated(
        address indexed market,
        bytes32 indexed poolId,
        uint256 wethSeeded,
        uint256 tokensSeeded,
        uint256 positionIdOrAmount
    );

    /// @dev Accept native ETH only from the immutable WETH contract while
    ///      unwrapping V4 rounding dust after graduation.
    receive() external payable {
        require(msg.sender == address(WETH), "adapter curve: only weth");
    }

    constructor(address creator, Infra memory infra, TokenConfig memory t, CurveConfig memory c) {
        require(creator != address(0), "adapter curve: zero creator");
        require(infra.treasury != address(0), "adapter curve: zero treasury");
        require(address(infra.liquidityAdapter).code.length > 0, "adapter curve: invalid adapter");
        require(address(infra.swapRouter).code.length > 0, "adapter curve: invalid router");
        require(address(infra.weth).code.length > 0, "adapter curve: invalid weth");
        require(infra.liquidityAdapter.weth() == address(infra.weth), "adapter curve: weth mismatch");
        require(infra.keeper != address(0), "adapter curve: zero keeper");
        require(address(infra.stockSwapExecutor) != address(0), "adapter curve: zero executor");
        require(t.totalSupply > 0, "adapter curve: zero supply");
        require(t.taxBps >= 100 && t.taxBps <= 500, "adapter curve: tax out of range");
        require(t.creatorFeeBps <= 100 && uint256(t.taxBps) + t.creatorFeeBps <= 600, "adapter curve: fee out of range");
        require(address(t.stock) != address(0), "adapter curve: zero stock");
        require(c.curvePct >= 50 && c.curvePct < 100, "adapter curve: bad curve pct");
        require(c.virtualEth > 0 && c.gradEth > 0, "adapter curve: bad params");
        require(uint256(c.gradEth) <= 9 * uint256(c.virtualEth), "adapter curve: grad unreachable");
        require(c.poolFee == infra.tokenPoolFee, "adapter curve: wrong pool fee");

        CREATOR = creator;
        TREASURY = infra.treasury;
        LIQUIDITY_ADAPTER = infra.liquidityAdapter;
        SWAP_ROUTER = infra.swapRouter;
        WETH = infra.weth;
        POOL_FEE = infra.tokenPoolFee;
        STOCK_POOL_FEE = infra.stockPoolFee;
        KEEPER = infra.keeper;

        tokenName = t.name;
        tokenSymbol = t.symbol;
        TOTAL_SUPPLY = t.totalSupply;
        TAX_BPS = t.taxBps;
        CREATOR_FEE_BPS = t.creatorFeeBps;
        STOCK = t.stock;

        uint256 curveSupply = (t.totalSupply * c.curvePct) / 100;
        require(curveSupply > 0, "adapter curve: curve supply zero");
        CURVE_SUPPLY = curveSupply;
        LP_SUPPLY = t.totalSupply - curveSupply;
        GRAD_ETH = c.gradEth;
        ethReserve = c.virtualEth;
        tokenReserve = curveSupply;
        K = uint256(c.virtualEth) * curveSupply;

        uint256 tokensAtGraduation = Math.ceilDiv(K, uint256(c.virtualEth) + c.gradEth) + LP_SUPPLY;
        infra.liquidityAdapter.validateSeedAmounts(tokensAtGraduation, c.gradEth);

        token = ArchTokenDeployLib.deploy(
            t.name,
            t.symbol,
            t.totalSupply,
            t.taxBps,
            t.stock,
            ArchToken.DexConfig({
                swapRouter: infra.swapRouter,
                weth: infra.weth,
                tokenPoolFee: infra.tokenPoolFee,
                stockPoolFee: infra.stockPoolFee,
                stockSwapExecutor: infra.stockSwapExecutor
            }),
            infra.treasury,
            infra.keeper,
            t.creatorFeeBps,
            creator,
            bytes32(0)
        );
        token.setTaxExempt(address(LIQUIDITY_ADAPTER));
        token.setLiquidityProvisioner(LIQUIDITY_ADAPTER.liquidityProvisioner());
    }

    function quoteBuy(uint256 ethIn) public view returns (uint256 tokensOut, uint256 fee) {
        fee = (ethIn * TRADE_FEE_BPS) / 10_000;
        uint256 net = ethIn - fee;
        if (realEthCollected + net > GRAD_ETH) return (0, fee);
        uint256 newTokenReserve = Math.ceilDiv(K, ethReserve + net);
        tokensOut = tokenReserve - newTokenReserve;
    }

    function quoteSell(uint256 tokensIn) public view returns (uint256 ethOut, uint256 fee) {
        uint256 newEthReserve = Math.ceilDiv(K, tokenReserve + tokensIn);
        uint256 grossEth = ethReserve - newEthReserve;
        fee = (grossEth * TRADE_FEE_BPS) / 10_000;
        ethOut = grossEth - fee;
    }

    /// @notice Exact gross ETH that reaches the remaining graduation target
    ///         after the 1% floor-rounded trade fee. Frontends can use this to
    ///         avoid an overshooting transaction near graduation.
    function graduationBuyAmount() external view returns (uint256) {
        uint256 remaining = uint256(GRAD_ETH) - realEthCollected;
        return remaining == 0 ? 0 : remaining + (remaining / 99);
    }

    function buy(uint256 minTokensOut) external payable nonReentrant {
        require(!graduated, "adapter curve: graduated");
        require(msg.value > 0, "adapter curve: zero value");
        uint256 fee = (msg.value * TRADE_FEE_BPS) / 10_000;
        uint256 net = msg.value - fee;
        require(realEthCollected + net <= GRAD_ETH, "adapter curve: exceeds graduation");
        uint256 newEthReserve = ethReserve + net;
        uint256 newTokenReserve = Math.ceilDiv(K, newEthReserve);
        uint256 tokensOut = tokenReserve - newTokenReserve;
        require(tokensOut >= minTokensOut && tokensOut > 0, "adapter curve: slippage");

        ethReserve = newEthReserve;
        tokenReserve = newTokenReserve;
        realEthCollected += net;
        (bool paid,) = TREASURY.call{value: fee}("");
        require(paid, "adapter curve: fee send failed");
        IERC20(address(token)).safeTransfer(msg.sender, tokensOut);
        emit Bought(msg.sender, msg.value, fee, tokensOut);
        if (realEthCollected == GRAD_ETH) _graduate();
    }

    function sell(uint256 tokensIn, uint256 minEthOut) external nonReentrant {
        require(!graduated, "adapter curve: graduated");
        require(tokensIn > 0, "adapter curve: zero tokens");
        uint256 newTokenReserve = tokenReserve + tokensIn;
        uint256 newEthReserve = Math.ceilDiv(K, newTokenReserve);
        uint256 grossEth = ethReserve - newEthReserve;
        uint256 fee = (grossEth * TRADE_FEE_BPS) / 10_000;
        uint256 ethOut = grossEth - fee;
        require(ethOut >= minEthOut && ethOut > 0, "adapter curve: slippage");

        ethReserve = newEthReserve;
        tokenReserve = newTokenReserve;
        realEthCollected -= grossEth;
        IERC20(address(token)).safeTransferFrom(msg.sender, address(this), tokensIn);
        (bool feePaid,) = TREASURY.call{value: fee}("");
        require(feePaid, "adapter curve: fee send failed");
        (bool paid,) = payable(msg.sender).call{value: ethOut}("");
        require(paid, "adapter curve: eth send failed");
        emit Sold(msg.sender, tokensIn, ethOut, fee);
    }

    function _graduate() private {
        ArchToken launched = token;
        uint256 tokensToLp = launched.balanceOf(address(this));
        uint256 ethToLp = realEthCollected;
        WETH.deposit{value: ethToLp}();
        launched.approve(address(LIQUIDITY_ADAPTER), tokensToLp);
        IERC20(address(WETH)).forceApprove(address(LIQUIDITY_ADAPTER), ethToLp);
        IArchLaunchLiquidityAdapter.SeedResult memory seeded = LIQUIDITY_ADAPTER.seed(
            IArchLaunchLiquidityAdapter.SeedParams({
                token: address(launched),
                tokenAmount: tokensToLp,
                wethAmount: ethToLp,
                lockOwner: address(0),
                unlockTime: 0,
                permanent: true
            })
        );
        launched.approve(address(LIQUIDITY_ADAPTER), 0);
        IERC20(address(WETH)).forceApprove(address(LIQUIDITY_ADAPTER), 0);
        require(seeded.tokenUsed > 0 && seeded.wethUsed > 0, "adapter curve: empty seed");
        require(seeded.tokenUsed <= tokensToLp && seeded.wethUsed <= ethToLp, "adapter curve: seed overflow");

        graduated = true;
        pair = seeded.market;
        poolId = seeded.poolId;
        launched.addMarketPair(seeded.market);
        launched.setDividendExempt(address(this));
        launched.setDividendExempt(address(launched));
        launched.setDividendExempt(DEAD);
        launched.setDividendExempt(address(LIQUIDITY_ADAPTER));
        launched.setDividendExempt(seeded.positionManager);

        uint256 tokenDust = tokensToLp - seeded.tokenUsed;
        if (tokenDust > 0) IERC20(address(launched)).safeTransfer(DEAD, tokenDust);
        uint256 wethDust = ethToLp - seeded.wethUsed;
        if (wethDust > 0) {
            WETH.withdraw(wethDust);
            (bool paid,) = TREASURY.call{value: wethDust}("");
            require(paid, "adapter curve: dust send failed");
        }

        launched.finalizeWiring();
        emit Graduated(seeded.market, seeded.poolId, seeded.wethUsed, seeded.tokenUsed, seeded.positionIdOrAmount);
    }
}

src/ArchAdapterCurveDeployer.sol.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {ArchAdapterBondingCurve} from "./ArchAdapterBondingCurve.sol";

/// @title ArchAdapterCurveDeployer
/// @notice Isolates bonding-curve creation bytecode from the versioned
///         launchpad. The deployer can be bound to exactly one launchpad.
contract ArchAdapterCurveDeployer {
    address public immutable ADMIN;
    address public launchpad;

    constructor() {
        ADMIN = msg.sender;
    }

    function setLaunchpad(address launchpad_) external {
        require(msg.sender == ADMIN && launchpad == address(0) && launchpad_ != address(0), "adapter deployer: auth");
        require(launchpad_.code.length > 0, "adapter deployer: invalid launchpad");
        launchpad = launchpad_;
    }

    function deploy(
        address creator,
        ArchAdapterBondingCurve.Infra calldata infra,
        ArchAdapterBondingCurve.TokenConfig calldata tokenConfig,
        ArchAdapterBondingCurve.CurveConfig calldata curveConfig
    ) external returns (address) {
        require(msg.sender == launchpad, "adapter deployer: only launchpad");
        return address(new ArchAdapterBondingCurve(creator, infra, tokenConfig, curveConfig));
    }
}

src/ArchToken.sol.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {IArchStockSwapExecutor} from "./interfaces/IArchStockSwapExecutor.sol";
import {ISwapRouter, IWETH9} from "./interfaces/IUniswapV3.sol";

/// @title ArchToken
/// @notice The ArchLiquid token standard: a fixed-supply ERC20 that is an RWA
///         distributor by construction. An immutable tax on AMM trades
///         accumulates in the token, is periodically sold for ETH, split
///         90/10 (holders/protocol), and the holders' share market-buys a
///         Robinhood stock token which streams pro rata to holders via
///         dividend accounting. Hold it, get paid in stocks.
///
///         There is no owner. All parameters are immutable after the factory
///         finalizes wiring in the deployment transaction. No mint function
///         exists, no blacklist exists, the tax can never be raised or
///         redirected.
contract ArchToken is ERC20, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    uint256 private constant MAGNITUDE = 2 ** 128;
    uint16 public constant MAX_TAX_BPS = 500; // 5%
    uint16 public constant MIN_TAX_BPS = 100; // 1%
    /// @notice Share of every distribution harvest that funds the protocol.
    uint16 public constant PROTOCOL_SHARE_BPS = 1000; // 10%
    /// @notice Max creator fee, stacked on top of the trade tax (1%).
    uint16 public constant MAX_CREATOR_FEE_BPS = 100;
    /// @notice Ceiling on trade tax + creator fee combined (6%).
    uint16 public constant MAX_TOTAL_BPS = 600;
    /// @notice Idle window after which unclaimed creator fees can revert to holders.
    uint64 public constant CREATOR_INACTIVITY = 30 days;

    /// @notice Immutable trade tax in basis points, set at deploy.
    uint16 public immutable TAX_BPS;
    /// @notice Immutable creator fee in bps, stacked on top of the trade tax.
    uint16 public immutable CREATOR_FEE_BPS;
    /// @notice TAX_BPS + CREATOR_FEE_BPS: the total taken on each taxed trade.
    uint16 public immutable TOTAL_FEE_BPS;
    IERC20 public immutable STOCK;
    /// @notice Uniswap V3 swap router and WETH used to run distributions.
    ISwapRouter public immutable SWAP_ROUTER;
    IWETH9 public immutable WETH;
    uint24 public immutable TOKEN_POOL_FEE; // fee tier of this token's own WETH pool
    uint24 public immutable STOCK_POOL_FEE; // direct stock/WETH fallback fee tier
    IArchStockSwapExecutor public immutable STOCK_SWAP_EXECUTOR;
    address payable public immutable TREASURY;
    /// @notice Protocol keeper that runs distributions with slippage bounds.
    address public immutable KEEPER;
    address public immutable FACTORY;

    /// @dev AMM pairs whose trades are taxed. Set during wiring only.
    mapping(address => bool) public isMarketPair;
    /// @dev Exempt from the trade tax (factory + this contract, for pool
    ///      seeding and distribution swaps). Set in constructor only.
    mapping(address => bool) public isTaxExempt;
    /// @dev Excluded from dividends: pairs, factory, locker, dead address.
    mapping(address => bool) public isDividendExempt;

    bool public wired;
    address public liquidityProvisioner;
    uint256 public marketPairCount;

    /// @dev Sum of balances that participate in dividends.
    uint256 public dividendTotalSupply;
    uint256 public magnifiedDividendPerShare;
    uint256 public totalDistributed;
    mapping(address => int256) private _corrections;
    mapping(address => uint256) public withdrawnDividends;

    /* ── creator fee + community takeover ──────────────────────────── */
    /// @notice Where the creator fee is paid. Starts as the creator and is the
    ///         only mutable economic value on the token, movable only by the
    ///         disclosed rules (voluntary handoff, or revert-to-holders on idle).
    address public creatorFeeRecipient;
    /// @notice Creator-fee ETH accrued and pull-claimable by the recipient.
    uint256 public creatorFeeAccrued;
    /// @notice Last recipient claim/handoff; resets the idle clock.
    uint64 public lastCreatorClaim;
    /// @notice Once true, the creator leg permanently reverts to holders.
    bool public creatorCtoActive;

    event MarketPairAdded(address indexed pair);
    event TaxExemptSet(address indexed account);
    event LiquidityProvisionerSet(address indexed provisioner);
    event DividendExemptSet(address indexed account);
    event WiringFinalized();
    event DistributionPrepared(uint256 wethAmount, uint256 protocolEth);
    event Distributed(uint256 stockAmount, uint256 protocolEth);
    event DividendClaimed(address indexed holder, uint256 amount);
    event CreatorFeeAccrued(uint256 ethAmount);
    event CreatorFeeClaimed(address indexed recipient, uint256 ethAmount);
    event CreatorFeeRecipientChanged(address indexed from, address indexed to);
    event CreatorCtoTriggered(uint256 strandedReverted);

    modifier onlyFactoryWiring() {
        require(msg.sender == FACTORY, "arch: not factory");
        require(!wired, "arch: wiring finalized");
        _;
    }

    struct DexConfig {
        ISwapRouter swapRouter;
        IWETH9 weth;
        uint24 tokenPoolFee;
        uint24 stockPoolFee;
        IArchStockSwapExecutor stockSwapExecutor;
    }

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        uint16 taxBps_,
        IERC20 stock_,
        DexConfig memory dex_,
        address payable treasury_,
        address keeper_,
        uint16 creatorFeeBps_,
        address creator_
    ) ERC20(name_, symbol_) {
        require(taxBps_ >= MIN_TAX_BPS && taxBps_ <= MAX_TAX_BPS, "arch: tax out of range");
        require(creatorFeeBps_ <= MAX_CREATOR_FEE_BPS, "arch: creator fee too high");
        require(uint256(taxBps_) + creatorFeeBps_ <= MAX_TOTAL_BPS, "arch: total fee too high");
        require(creatorFeeBps_ == 0 || creator_ != address(0), "arch: zero creator");
        require(address(stock_) != address(0), "arch: zero stock");
        require(address(dex_.swapRouter) != address(0), "arch: zero router");
        require(address(dex_.weth) != address(0), "arch: zero weth");
        require(address(dex_.stockSwapExecutor) != address(0), "arch: zero executor");
        require(treasury_ != address(0), "arch: zero treasury");
        require(keeper_ != address(0), "arch: zero keeper");
        require(totalSupply_ > 0, "arch: zero supply");

        TAX_BPS = taxBps_;
        CREATOR_FEE_BPS = creatorFeeBps_;
        TOTAL_FEE_BPS = taxBps_ + creatorFeeBps_;
        creatorFeeRecipient = creator_;
        lastCreatorClaim = uint64(block.timestamp);
        STOCK = stock_;
        SWAP_ROUTER = dex_.swapRouter;
        WETH = dex_.weth;
        TOKEN_POOL_FEE = dex_.tokenPoolFee;
        STOCK_POOL_FEE = dex_.stockPoolFee;
        STOCK_SWAP_EXECUTOR = dex_.stockSwapExecutor;
        TREASURY = treasury_;
        KEEPER = keeper_;
        FACTORY = msg.sender;

        isTaxExempt[msg.sender] = true;
        isTaxExempt[address(this)] = true;

        _mint(msg.sender, totalSupply_);
    }

    /// @notice Accept ETH from the router during distribution swaps.
    receive() external payable {}

    /* ── factory wiring (deployment transaction only) ────────────── */

    function addMarketPair(address pair) external onlyFactoryWiring {
        _addMarketPair(pair);
    }

    /// @notice Exempts immutable liquidity infrastructure while the creating
    ///         factory is still wiring the token. This is deliberately closed
    ///         after `finalizeWiring`: users can add to the already-registered
    ///         pool through that reviewed provisioner, but nobody can add a
    ///         later arbitrary tax bypass.
    function setTaxExempt(address account) external onlyFactoryWiring {
        require(account != address(0) && account.code.length > 0, "arch: invalid exemption");
        require(!isTaxExempt[account], "arch: already exempt");
        isTaxExempt[account] = true;
        emit TaxExemptSet(account);
    }

    /// @notice Binds the sole post-wiring entry point that may register this
    ///         token's first market. The creating factory fixes it before
    ///         `finalizeWiring`; it can never be replaced afterward.
    function setLiquidityProvisioner(address provisioner) external onlyFactoryWiring {
        require(provisioner.code.length > 0, "arch: invalid provisioner");
        require(liquidityProvisioner == address(0), "arch: provisioner set");
        liquidityProvisioner = provisioner;
        emit LiquidityProvisionerSet(provisioner);
    }

    /// @notice Registers a deferred first market created by the immutable
    ///         family adapter through the bound provisioner. Additional or
    ///         arbitrary post-wiring markets remain impossible.
    function registerInitialMarketPair(address pair) external {
        require(wired, "arch: wiring incomplete");
        require(msg.sender == liquidityProvisioner, "arch: not provisioner");
        require(marketPairCount == 0, "arch: market already set");
        _addMarketPair(pair);
    }

    function setDividendExempt(address account) external onlyFactoryWiring {
        _setDividendExempt(account);
    }

    function finalizeWiring() external onlyFactoryWiring {
        wired = true;
        emit WiringFinalized();
    }

    function _addMarketPair(address pair) private {
        require(pair != address(0), "arch: zero pair");
        require(!isMarketPair[pair], "arch: pair already set");
        isMarketPair[pair] = true;
        marketPairCount += 1;
        _setDividendExempt(pair);
        emit MarketPairAdded(pair);
    }

    /* ── transfers + tax ─────────────────────────────────────────── */

    function _update(address from, address to, uint256 value) internal override {
        bool taxable = value > 0 && (isMarketPair[from] || isMarketPair[to]) && !isTaxExempt[from] && !isTaxExempt[to];
        if (taxable) {
            uint256 fee = (value * TOTAL_FEE_BPS) / 10_000;
            if (fee > 0) _move(from, address(this), fee);
            _move(from, to, value - fee);
        } else {
            _move(from, to, value);
        }
    }

    /// @dev Executes the balance change and mirrors it into dividend
    ///      accounting so participating supply always matches balances.
    function _move(address from, address to, uint256 value) private {
        super._update(from, to, value);
        if (from != address(0) && !isDividendExempt[from]) {
            _corrections[from] += (magnifiedDividendPerShare * value).toInt256();
            dividendTotalSupply -= value;
        }
        if (to != address(0) && !isDividendExempt[to]) {
            _corrections[to] -= (magnifiedDividendPerShare * value).toInt256();
            dividendTotalSupply += value;
        }
    }

    function _setDividendExempt(address account) private {
        if (isDividendExempt[account]) return;
        isDividendExempt[account] = true;
        uint256 bal = balanceOf(account);
        if (bal > 0) {
            _corrections[account] += (magnifiedDividendPerShare * bal).toInt256();
            dividendTotalSupply -= bal;
        }
        emit DividendExemptSet(account);
    }

    /* ── distribution ────────────────────────────────────────────── */

    /// @notice Sell the accumulated tax for WETH on this token's V3 pool,
    ///         forward the protocol share to the treasury as ETH, buy the stock
    ///         token with the rest on its direct V3 pool, and credit it pro
    ///         rata to holders. This remains available for stock/WETH pools
    ///         with sufficient direct liquidity.
    function processDistribution(uint256 minEthOut, uint256 minStockOut) external nonReentrant {
        _requireDistributionReady();
        uint256 protocolWeth = _sellTaxForWeth(minEthOut);
        uint256 buyWeth = WETH.balanceOf(address(this));
        uint256 stockGot = _buyStockDirect(buyWeth, minStockOut);
        _creditDistribution(stockGot, protocolWeth);
    }

    /// @notice Sell accumulated tax for WETH and pay the protocol share. The
    ///         remaining exact WETH balance can then be quoted off chain and
    ///         consumed by `processDistributionViaExecutor`.
    function prepareDistribution(uint256 minEthOut) external nonReentrant {
        _requireDistributionReady();
        uint256 protocolWeth = _sellTaxForWeth(minEthOut);
        emit DistributionPrepared(WETH.balanceOf(address(this)), protocolWeth);
    }

    /// @notice Buy stock from a previously prepared WETH balance through the
    ///         immutable constrained executor. Generate `swapData` with this
    ///         token's current WETH balance as the exact input amount and the
    ///         executor as both 1inch `from` and `receiver`.
    function processDistributionViaExecutor(uint256 minStockOut, bytes calldata swapData) external nonReentrant {
        require(msg.sender == KEEPER, "arch: not keeper");
        require(wired, "arch: not wired");
        require(dividendTotalSupply > 0, "arch: no participants");
        require(swapData.length >= 4, "arch: missing swap data");

        uint256 buyWeth = WETH.balanceOf(address(this));
        require(buyWeth > 0, "arch: no prepared weth");
        uint256 stockGot = _buyStockViaExecutor(buyWeth, minStockOut, swapData);
        require(WETH.balanceOf(address(this)) == 0, "arch: unspent weth");
        _creditDistribution(stockGot, 0);
    }

    function _requireDistributionReady() private view {
        require(msg.sender == KEEPER, "arch: not keeper");
        require(wired, "arch: not wired");
        uint256 tokenBal = balanceOf(address(this));
        require(tokenBal > 0, "arch: nothing to process");
        require(dividendTotalSupply > 0, "arch: no participants");
    }

    function _sellTaxForWeth(uint256 minEthOut) private returns (uint256 protocolWeth) {
        uint256 tokenBal = balanceOf(address(this));

        // sell the tax tokens for WETH on this token's own pool (this contract
        // is tax-exempt, so the full balance reaches the pool untaxed)
        _approve(address(this), address(SWAP_ROUTER), tokenBal);
        uint256 wethGot = SWAP_ROUTER.exactInputSingle(
            ISwapRouter.ExactInputSingleParams({
                tokenIn: address(this),
                tokenOut: address(WETH),
                fee: TOKEN_POOL_FEE,
                recipient: address(this),
                amountIn: tokenBal,
                amountOutMinimum: minEthOut,
                sqrtPriceLimitX96: 0
            })
        );
        require(wethGot > 0, "arch: no weth from swap");

        // creator fee (stacked on top of the tax): peel it off as pull-claimable
        // ETH for the creator. After a community takeover reverts the stream the
        // creator leg stops accruing, and any stranded balance folds back into the
        // holder/protocol pool below so it reaches holders.
        uint256 pool = wethGot;
        if (CREATOR_FEE_BPS > 0 && !creatorCtoActive) {
            uint256 creatorCut = (wethGot * CREATOR_FEE_BPS) / TOTAL_FEE_BPS;
            if (creatorCut > 0) {
                WETH.withdraw(creatorCut);
                creatorFeeAccrued += creatorCut;
                pool -= creatorCut;
                emit CreatorFeeAccrued(creatorCut);
            }
        } else if (creatorCtoActive && creatorFeeAccrued > 0) {
            uint256 stranded = creatorFeeAccrued;
            creatorFeeAccrued = 0;
            WETH.deposit{value: stranded}();
            pool += stranded;
        }

        // protocol share: unwrap to ETH and forward to the treasury
        protocolWeth = (pool * PROTOCOL_SHARE_BPS) / 10_000;
        if (protocolWeth > 0) {
            WETH.withdraw(protocolWeth);
            (bool ok,) = TREASURY.call{value: protocolWeth}("");
            require(ok, "arch: treasury send failed");
        }
    }

    function _creditDistribution(uint256 stockGot, uint256 protocolWeth) private {
        require(stockGot > 0, "arch: no stock bought");

        magnifiedDividendPerShare += (stockGot * MAGNITUDE) / dividendTotalSupply;
        totalDistributed += stockGot;
        emit Distributed(stockGot, protocolWeth);
    }

    function _buyStockDirect(uint256 buyWeth, uint256 minStockOut) private returns (uint256 stockGot) {
        IERC20(address(WETH)).forceApprove(address(SWAP_ROUTER), buyWeth);
        stockGot = SWAP_ROUTER.exactInputSingle(
            ISwapRouter.ExactInputSingleParams({
                tokenIn: address(WETH),
                tokenOut: address(STOCK),
                fee: STOCK_POOL_FEE,
                recipient: address(this),
                amountIn: buyWeth,
                amountOutMinimum: minStockOut,
                sqrtPriceLimitX96: 0
            })
        );
        IERC20(address(WETH)).forceApprove(address(SWAP_ROUTER), 0);
    }

    function _buyStockViaExecutor(uint256 buyWeth, uint256 minStockOut, bytes memory swapData)
        private
        returns (uint256 stockGot)
    {
        address executor = address(STOCK_SWAP_EXECUTOR);

        uint256 stockBefore = STOCK.balanceOf(address(this));
        IERC20(address(WETH)).forceApprove(executor, buyWeth);
        STOCK_SWAP_EXECUTOR.swapExactWethForStock(address(STOCK), buyWeth, minStockOut, swapData);
        IERC20(address(WETH)).forceApprove(executor, 0);

        stockGot = STOCK.balanceOf(address(this)) - stockBefore;
        require(stockGot >= minStockOut, "arch: insufficient stock");
    }

    /* ── creator fee: claim, handoff, community takeover ───────────── */

    /// @notice Pull the accrued creator fee to the recipient. Only the recipient
    ///         can call, and doing so resets the idle clock (proof of life).
    function claimCreatorFee() external nonReentrant {
        require(!creatorCtoActive, "arch: cto active");
        require(msg.sender == creatorFeeRecipient, "arch: not creator");
        uint256 amount = creatorFeeAccrued;
        require(amount > 0, "arch: nothing to claim");
        creatorFeeAccrued = 0;
        lastCreatorClaim = uint64(block.timestamp);
        (bool ok,) = creatorFeeRecipient.call{value: amount}("");
        require(ok, "arch: creator send failed");
        emit CreatorFeeClaimed(creatorFeeRecipient, amount);
    }

    /// @notice Voluntary handoff of the creator-fee stream (a clean takeover).
    function setCreatorFeeRecipient(address newRecipient) external {
        require(!creatorCtoActive, "arch: cto active");
        require(msg.sender == creatorFeeRecipient, "arch: not creator");
        require(newRecipient != address(0), "arch: zero recipient");
        emit CreatorFeeRecipientChanged(creatorFeeRecipient, newRecipient);
        creatorFeeRecipient = newRecipient;
        lastCreatorClaim = uint64(block.timestamp);
    }

    /// @notice Community takeover: once the creator has left fees unclaimed past
    ///         the idle window, anyone can permanently revert the creator leg to
    ///         holders. The rule is fixed and disclosed at deploy; there is no
    ///         privileged party and no new beneficiary to dispute. The stranded
    ///         accrual folds into the next distribution for holders.
    function revertCreatorFeeToHolders() external {
        require(CREATOR_FEE_BPS > 0 && !creatorCtoActive, "arch: no creator leg");
        require(creatorFeeAccrued > 0, "arch: nothing unclaimed");
        require(block.timestamp > uint256(lastCreatorClaim) + CREATOR_INACTIVITY, "arch: creator active");
        creatorCtoActive = true;
        creatorFeeRecipient = address(0);
        emit CreatorCtoTriggered(creatorFeeAccrued);
    }

    /* ── dividends ───────────────────────────────────────────────── */

    function accumulativeDividendOf(address account) public view returns (uint256) {
        if (isDividendExempt[account]) return withdrawnDividends[account];
        return uint256((magnifiedDividendPerShare * balanceOf(account)).toInt256() + _corrections[account]) / MAGNITUDE;
    }

    function withdrawableDividendOf(address account) public view returns (uint256) {
        return accumulativeDividendOf(account) - withdrawnDividends[account];
    }

    function claim() external nonReentrant {
        _claim(msg.sender);
    }

    /// @notice Anyone may trigger a claim for a holder; stock always goes to
    ///         the holder. The protocol keeper uses this to push payouts.
    function claimFor(address holder) external nonReentrant {
        _claim(holder);
    }

    function _claim(address holder) private {
        uint256 amount = withdrawableDividendOf(holder);
        require(amount > 0, "arch: nothing to claim");
        withdrawnDividends[holder] += amount;
        STOCK.safeTransfer(holder, amount);
        emit DividendClaimed(holder, amount);
    }
}

