src/interfaces/IUniswapV3.sol.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity ^0.8.10;

interface IUniswapV3Factory {
    function getPool(address tokenA, address tokenB, uint24 fee) external view returns (address pool);
    function createPool(address tokenA, address tokenB, uint24 fee) external returns (address pool);
}

interface IUniswapV3PoolMinimal {
    function initialize(uint160 sqrtPriceX96) external;
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );
    function token0() external view returns (address);
    function token1() external view returns (address);
}

/// @notice Subset of Uniswap V3 NonfungiblePositionManager (also an ERC-721).
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    function createAndInitializePoolIfNecessary(address token0, address token1, uint24 fee, uint160 sqrtPriceX96)
        external
        payable
        returns (address pool);

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);

    function collect(CollectParams calldata params) external payable returns (uint256 amount0, uint256 amount1);

    function positions(uint256 tokenId)
        external
        view
        returns (
            uint96 nonce,
            address operator,
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        );

    // ERC-721
    function ownerOf(uint256 tokenId) external view returns (address);
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
    function transferFrom(address from, address to, uint256 tokenId) external;
    function approve(address to, uint256 tokenId) external;
}

interface ISwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
    function exactInput(ExactInputParams calldata params) external payable returns (uint256 amountOut);
}

interface IWETH9 {
    function deposit() external payable;
    function withdraw(uint256) external;
    function approve(address, uint256) external returns (bool);
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

src/lib/ArchTokenDeployLib.sol.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ArchToken} from "../ArchToken.sol";

/// @title ArchTokenDeployLib
/// @notice Deploys ArchToken instances via CREATE2. This is a `public` (external,
///         delegatecall-linked) library, so the ArchToken creation bytecode lives
///         in the library's own deployed code, NOT inlined into every caller.
///         That keeps ArchPresale and ArchBondingCurve creation code small
///         enough that their deployers stay under the EIP-170 24KB limit.
///
///         Because the library is delegatecalled, `address(this)` inside `deploy`
///         is the CALLER (the presale/curve/factory), so the CREATE2 is executed
///         from the caller's address: the resulting token address and its
///         immutable FACTORY (= msg.sender in the ArchToken constructor) are
///         identical to a direct `new ArchToken{salt}` in the caller. No wiring
///         or address semantics change.
library ArchTokenDeployLib {
    function deploy(
        string memory name,
        string memory symbol,
        uint256 totalSupply,
        uint16 taxBps,
        IERC20 stock,
        ArchToken.DexConfig memory dex,
        address payable treasury,
        address keeper,
        uint16 creatorFeeBps,
        address creator,
        bytes32 salt
    ) public returns (ArchToken) {
        return new ArchToken{salt: salt}(
            name, symbol, totalSupply, taxBps, stock, dex, treasury, keeper, creatorFeeBps, creator
        );
    }
}
